export function getPBMLAProfile(acNo: number): MLAProfile | undefined {
  return PB_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getPBMLAsByParty(party: string): MLAProfile[] {
  return PB_MLA_PROFILES.filter(p => p.party === party);
}

export function getPBFemaleMLAs(): MLAProfile[] {
  return PB_MLA_PROFILES.filter(p => p.gender === 'F');
}
